'use client';

import type { CSSProperties, ReactNode } from 'react';
import { cn } from '@/lib/utils';
import art from './art.json';
import './halloween.css';

// generated by scripts/halloween-art.mjs; edit the models there, never this JSON
type Model = { viewBox: number[]; runs: string[][]; anchors: Record<string, number[]> };
export type ModelName = Exclude<keyof typeof art, 'cobweb'>;

export const model = (name: ModelName) => art[name] as Model;

// where an anchor of the model sits inside the drawing, as percentages for absolute children
export function anchorAt(name: ModelName, anchor: string) {
  const { viewBox, anchors } = model(name);
  const [x, y] = anchors[anchor];
  return { left: `${((x - viewBox[0]) / viewBox[2]) * 100}%`, top: `${((y - viewBox[1]) / viewBox[3]) * 100}%` };
}

interface VoxelProps {
  readonly name: ModelName;
  readonly className?: string;
  readonly style?: CSSProperties;
  readonly children?: ReactNode;
}

export function Voxel({ name, className, style, children }: VoxelProps) {
  const { viewBox, runs } = model(name);
  return (
    <svg viewBox={viewBox.join(' ')} className={cn('hw-voxel', className)} style={style} aria-hidden="true">
      {runs.map(([part, fill, d], i) => (
        <path key={i} data-part={part} d={d} fill={fill} stroke={fill} />
      ))}
      {children}
    </svg>
  );
}

export function Cobweb({ className }: { readonly className?: string }) {
  return (
    <svg viewBox={art.cobweb.viewBox.join(' ')} className={className} aria-hidden="true">
      <path d={art.cobweb.d} fill="none" stroke="#d8cdf0" strokeWidth="0.7" strokeLinecap="round" />
    </svg>
  );
}
